import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static int nextInt() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        int r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        int[] s = new int[n];
        for (int i = 0; i < n; i++) s[i] = nextInt();
        Arrays.sort(s);
        // Walk in descending order; equal scores share a rank, a new score's rank is its index + 1.
        long ans = 0;
        int rank = 1;
        for (int i = 0; i < n; i++) {
            int cur = s[n - 1 - i];
            if (i > 0 && cur != s[n - i]) rank = i + 1;
            if (rank <= k && cur > 0) ans++;
        }
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(in, &n, &k)
	s := make([]int, n)
	for i := range s {
		fmt.Fscan(in, &s[i])
	}
	sort.Sort(sort.Reverse(sort.IntSlice(s)))
	// Competition ranking: equal scores share a rank, a new score's rank is its index + 1.
	ans, rank := 0, 1
	for i := 0; i < n; i++ {
		if i > 0 && s[i] != s[i-1] {
			rank = i + 1
		}
		if rank <= k && s[i] > 0 {
			ans++
		}
	}
	fmt.Println(ans)
}
